+export interface ManagedHostRunLaunchedWorkerHandle {
+  pid?: number;
+  exitCode: number | null;
+  signalCode: NodeJS.Signals | null;
+  kill(signal?: NodeJS.Signals | number): boolean;
+  once(event: 'close' | 'error', listener: () => void): unknown;
