          || seal.bindingDigest !== digestFile(paths.evidenceBinding)) {
          mismatches.push('binding');
        }
      }
    } catch {
      mismatches.push('binding');
    }
  }
  if (mismatches.length > 0) {
    throw new Error(`managed host run ${terminal.runId}: sealed artifact digest mismatch (${[...new Set(mismatches)].join(',')})`);
  }
}

